#include <stdio.h>
#include <stdlib.h>

static int *parent, *dsuSize;

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

void unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return;

    if (dsuSize[a] < dsuSize[b]) {
        int tmp = a;
        a = b;
        b = tmp;
    }
    parent[b] = a;
    dsuSize[a] += dsuSize[b];
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *head = (int *)malloc((N + 1) * sizeof(int));
    int *to = (int *)malloc((2 * M + 5) * sizeof(int));
    int *nxt = (int *)malloc((2 * M + 5) * sizeof(int));
    parent = (int *)malloc((N + 1) * sizeof(int));
    dsuSize = (int *)malloc((N + 1) * sizeof(int));
    int *deg = (int *)calloc(N + 1, sizeof(int));

    for (int i = 1; i <= N; i++) {
        head[i] = -1;
        parent[i] = i;
        dsuSize[i] = 1;
    }

    int ec = 0;
    for (int i = 0; i < M; i++) {
        int u, v;
        scanf("%d %d", &u, &v);

        deg[u]++;
        deg[v]++;

        to[ec] = v;
        nxt[ec] = head[u];
        head[u] = ec++;

        to[ec] = u;
        nxt[ec] = head[v];
        head[v] = ec++;

        unite(u, v);
    }

    for (int i = 1; i <= N; i++) {
        parent[i] = find(i);
    }

    int *compHead = (int *)malloc((N + 1) * sizeof(int));
    int *compNext = (int *)malloc((N + 1) * sizeof(int));
    int *compSize = (int *)calloc(N + 1, sizeof(int));

    for (int i = 1; i <= N; i++) {
        compHead[i] = -1;
    }

    for (int v = 1; v <= N; v++) {
        int r = parent[v];
        compNext[v] = compHead[r];
        compHead[r] = v;
        compSize[r]++;
    }

    char *mark = (char *)calloc(N + 1, sizeof(char));

    for (int r = 1; r <= N; r++) {
        int s = compSize[r];
        if (s < 3) continue;

        int cand = -1;
        for (int v = compHead[r]; v != -1; v = compNext[v]) {
            if (deg[v] != s - 1) {
                cand = v;
                break;
            }
        }

        if (cand != -1) {
            for (int e = head[cand]; e != -1; e = nxt[e]) {
                mark[to[e]] = 1;
            }

            for (int u = compHead[r]; u != -1; u = compNext[u]) {
                if (u != cand && !mark[u]) {
                    printf("%d %d\n", cand, u);
                    return 0;
                }
            }
        }
    }

    printf("-1\n");
    return 0;
}
